{
  "schemaVersion": "0.2",
  "slug": "iot-panel",
  "name": "IoT panel",
  "status": "experimental",
  "purpose": "Device cards with status badges, load gauges, and trend charts.",
  "scenarios": [
    "Scan online, alert, and offline devices",
    "Acknowledge an alert to return a device to online",
    "Show an empty state when no devices are connected"
  ],
  "props": {
    "locale": {
      "type": "string",
      "required": false,
      "description": "BCP 47 locale for bundled block copy.",
      "default": "en"
    },
    "onAcknowledge": {
      "type": "event",
      "required": false,
      "description": "Called when an alert device is acknowledged."
    }
  },
  "variants": [
    {
      "name": "density",
      "values": ["comfortable", "compact"],
      "default": "comfortable",
      "description": "Inherits density from token rungs rather than a local viewport query."
    }
  ],
  "states": [
    { "name": "default", "description": "Devices are present and none are alerting." },
    { "name": "alert", "description": "At least one device is alerting." },
    { "name": "empty", "description": "No devices to show." }
  ],
  "composition": {
    "allowedParents": ["page", "app-shell"],
    "allowedChildren": ["card", "gauge", "chart", "badge", "button", "empty-state", "typography"],
    "requiredContext": []
  },
  "antiPatterns": [
    "Do not present this template as a live SCADA or twin runtime.",
    "Do not size the device grid with viewport width media queries."
  ],
  "a11y": {
    "role": "region",
    "keyboard": ["Tab reaches badges, gauges, charts, and acknowledge actions"],
    "focus": "Acknowledge stays in document order with a visible focus ring.",
    "labeling": "Gauges and charts include the device name; badges name the status.",
    "wcag": ["1.1.1", "2.1.1", "4.1.2"]
  },
  "responsive": {
    "strategy": "Device cards stack; @container at 48rem places three columns. No viewport media queries.",
    "breakpoints": {
      "compact": "Cards stack to one column.",
      "medium": "Cards become three columns at 48rem container inline-size.",
      "large": "Cards remain three columns."
    }
  },
  "platforms": {
    "web": "supported",
    "react": "supported",
    "vue": "planned"
  },
  "rtl": {
    "supported": true,
    "strategy": "Logical CSS only. Direction comes from locale language.",
    "mirroredValues": []
  },
  "dataAi": {
    "role": "iot-panel",
    "states": ["default", "alert", "empty"],
    "intents": ["monitor-devices"]
  }
}

import { Badge, Button, Card, Chart, EmptyState, Gauge, Typography } from '@chameleon-ui/components-react'
import { useState } from 'react'
import { createBlockCopy } from '../copy.js'
import { iotPanelLocaleTrees } from './locale-map.js'
import './styles.css'

export type IotDeviceStatus = 'online' | 'offline' | 'alert'

export interface IotDevice {
  id: string
  name: string
  status: IotDeviceStatus
  metric: number
  series: number[]
}

export interface IotPanelProps {
  locale?: string
  devices?: IotDevice[]
  onAcknowledge?: (id: string) => void
  className?: string
}

const DEFAULT_DEVICES: IotDevice[] = [
  { id: 'alpha', name: 'Chiller A', status: 'online', metric: 42, series: [20, 28, 35, 42] },
  { id: 'bravo', name: 'Pump B', status: 'alert', metric: 88, series: [60, 72, 80, 88] },
  { id: 'charlie', name: 'Sensor C', status: 'offline', metric: 0, series: [] },
]

function badgeVariant(status: IotDeviceStatus): 'success' | 'danger' | 'default' {
  if (status === 'online') return 'success'
  if (status === 'alert') return 'danger'
  return 'default'
}

function statusKey(status: IotDeviceStatus) {
  if (status === 'online') return 'iot.statusOnline'
  if (status === 'alert') return 'iot.statusAlert'
  return 'iot.statusOffline'
}

function aiState(devices: IotDevice[]) {
  if (devices.length === 0) return 'empty'
  if (devices.some((device) => device.status === 'alert')) return 'alert'
  return 'default'
}

export function IotPanel({
  locale = 'en',
  devices: initialDevices = DEFAULT_DEVICES,
  onAcknowledge,
  className,
}: IotPanelProps) {
  const { t } = createBlockCopy(iotPanelLocaleTrees, locale)
  const [devices, setDevices] = useState<IotDevice[]>(initialDevices)
  const classes = ['cu-block-iot-panel', className].filter(Boolean).join(' ')

  const handleAcknowledge = (id: string) => {
    setDevices((current) =>
      current.map((device) => (device.id === id ? { ...device, status: 'online' } : device)),
    )
    onAcknowledge?.(id)
  }

  return (
    <section
      className={classes}
      data-ai-role="iot-panel"
      data-ai-intent="monitor-devices"
      data-ai-state={aiState(devices)}
    >
      <div className="cu-block-iot-panel__header">
        <Typography variant="heading-1">{t('iot.title')}</Typography>
        <Typography variant="body">{t('iot.subtitle')}</Typography>
        <p className="cu-block-iot-panel__meta">{t('iot.deviceCount', { count: devices.length })}</p>
      </div>
      {devices.length === 0 ? (
        <EmptyState description={t('iot.emptyDescription')} title={t('iot.emptyTitle')} />
      ) : (
        <div className="cu-block-iot-panel__devices">
          {devices.map((device) => (
            <Card className="cu-block-iot-panel__device" key={device.id} padding="md" variant="outlined">
              <div className="cu-block-iot-panel__device-head">
                <Typography variant="heading-2">{device.name}</Typography>
                <Badge variant={badgeVariant(device.status)}>{t(statusKey(device.status))}</Badge>
              </div>
              <Gauge
                label={t('iot.gaugeLabel', { name: device.name })}
                max={100}
                value={device.metric}
                valueLabel={`${device.metric}%`}
              />
              <Chart
                emptyLabel={t('iot.emptyChart')}
                label={t('iot.chartLabel', { name: device.name })}
                series={[{ name: device.name, data: device.series }]}
                type="line"
              />
              {device.status === 'alert' ? (
                <Button onClick={() => handleAcknowledge(device.id)} type="button" variant="outline">
                  {t('iot.acknowledge', { name: device.name })}
                </Button>
              ) : null}
            </Card>
          ))}
        </div>
      )}
    </section>
  )
}

{
  "slug": "iot-panel",
  "type": "registry:block",
  "name": "IoT panel",
  "dependencies": ["badge", "button", "card", "chart", "empty-state", "gauge", "typography"],
  "theme": { "constraints": [] },
  "rtl": true,
  "platforms": {
    "compact": true,
    "medium": true,
    "large": true
  },
  "preview": {
    "width": 768,
    "title": "Device cards with gauges, charts, and badges"
  }
}

.cu-block-iot-panel {
  container-type: inline-size;
  container-name: iot;
  display: grid;
  gap: var(--cu-space-3);
  padding-block: var(--cu-space-3);
  padding-inline: var(--cu-space-3);
}

.cu-block-iot-panel__header {
  display: grid;
  gap: var(--cu-space-2);
}

.cu-block-iot-panel__meta {
  margin-block: 0;
  color: var(--cu-color-fg-default);
  font-size: var(--cu-typography-size-caption);
}

.cu-block-iot-panel__devices {
  display: grid;
  gap: var(--cu-space-3);
  grid-template-columns: minmax(0, 1fr);
}

.cu-block-iot-panel__device {
  display: grid;
  gap: var(--cu-space-2);
}

.cu-block-iot-panel__device-head {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  justify-content: space-between;
  gap: var(--cu-space-2);
}

@container iot (min-inline-size: 48rem) {
  .cu-block-iot-panel__devices {
    grid-template-columns: repeat(3, minmax(0, 1fr));
  }
}
